select energy_manager.load_cards($cards$[
{"id":"p3-b03-024","paper":3,"topic":"Compressed Air System","kind":"problem","front":"A 35 m³/min compressor cycles with all users closed: average load time 1.5 min, unload time 10.5 min, and 188 kW drawn on load. Find the leakage rate, leakage per day, specific power of generation and energy lost to leakage per day.","back":"Leakage 4.375 m³/min, or 6300 m³/day. Specific power 0.0895 kWh/m³. Energy lost to leakage about 564 kWh/day.","explain":"The leak fraction is load time over total cycle time, applied to rated capacity. Leaked air still costs full compression energy, so the loss is a daily cost.","flash":false,"steps":[{"prompt":"Find the leakage rate.","answer":"q = 35 × 1.5 / (1.5 + 10.5) = 35 × 0.125 = 4.375 m³/min.","explain":"Leak fraction is the on-load time over the total cycle time."},{"prompt":"Find the leakage per day.","answer":"4.375 × 60 × 24 = 6300 m³/day.","explain":"Converts the per-minute rate to a 24-hour day."},{"prompt":"Find the specific power for compressed air generation.","answer":"188 kW / (35 × 60) m³/h = 0.0895 kWh/m³.","explain":"Full-load power divided by hourly delivery gives energy per cubic metre."},{"prompt":"Find the energy lost to leakage per day.","answer":"0.0895 × 6300 = 564 kWh/day.","explain":"Leaked volume times specific power gives the daily energy wasted."}],"source":"BEE Book 3 Ch 03 p115","order":3205},
{"id":"p3-b03-025","paper":3,"topic":"Compressed Air System","kind":"fact","front":"How much moisture does an aftercooler remove, and what happens to the rest?","back":"About 60–75% of the moisture is removed at the after-cooler. The rest condenses as the air cools in the lines, which is enough for cleaning and atomisation but not for instrument or pneumatic use.","explain":"Remaining vapour must be taken out by air dryers for instrumentation and pneumatics. Warm, humid air reaching the receivers increases condensation, corrosion and leakage.","flash":false,"source":"BEE Book 3 Ch 03 p116","order":3206},
{"id":"p3-b03-026","paper":3,"topic":"Compressed Air System","kind":"problem","front":"Air at an atmospheric dew point of −10°C and 1013.3 mbar holds water vapour at 2.8 mbar partial pressure. It is compressed to 2026.6 mbar. What are the new vapour partial pressure and the approximate dew point?","back":"Vapour partial pressure doubles to 5.6 mbar. The dew point rises to about −1°C.","explain":"Compression raises the dew point, so a dryer's performance is quoted as a pressure dew point, which is higher than the atmospheric figure.","flash":false,"steps":[{"prompt":"Find the pressure ratio.","answer":"2026.6 / 1013.3 = 2.","explain":"Total pressure doubles."},{"prompt":"Find the new water vapour partial pressure (Dalton's law).","answer":"2.8 × 2 = 5.6 mbar.","explain":"With the same moisture content, the partial pressure of vapour scales with total pressure."},{"prompt":"Find the new dew point.","answer":"About −1°C.","explain":"The book quotes approximately −1°C as the temperature at which 5.6 mbar of vapour condenses."}],"source":"BEE Book 3 Ch 03 p117","order":3207},
{"id":"p3-b03-027","paper":3,"topic":"Compressed Air System","kind":"fact","front":"How does a refrigerant dryer lower the dew point, and what dew point does it reach?","back":"It chills the air so moisture condenses out. A second heat exchanger has the outgoing cold air pre-cool the incoming air. Atmospheric dew point reaches about −20°C.","explain":"It is the most economical dryer for about 90% of applications. It removes almost 100% of solid particles and water droplets larger than 3 µm.","flash":true,"source":"BEE Book 3 Ch 03 p118","order":3208},
{"id":"p3-b03-028","paper":3,"topic":"Compressed Air System","kind":"fact","front":"How does a heat of compression (HOC) desiccant dryer regenerate its desiccant without an external heat source?","back":"It uses hot air taken straight from the compressor discharge, about 135°C from a reciprocating machine, before the after-cooler. No electric heater is fitted and there is no purge loss, so operating cost is zero or very low.","explain":"HOC dryers serve about 400 to 5000 cfm. Each vessel is in service for 4 hours while the other regenerates: 2.5 hours heating and 1.5 hours cooling.","flash":false,"source":"BEE Book 3 Ch 03 p119","order":3209},
{"id":"p3-b03-029","paper":3,"topic":"Compressed Air System","kind":"fact","front":"What is the purge loss of a heatless purge desiccant dryer, and below what capacity is it used?","back":"About 12–15% of the dry air is used for purging, so operating cost is very high. It is used for capacities below about 250 cfm.","explain":"Blower-reactivated dryers, used above 250 cfm, lose about 1–2% to purge but need a heater. HOC dryers have no purge loss at all.","flash":false,"source":"BEE Book 3 Ch 03 p119","order":3210},
{"id":"p3-b03-030","paper":3,"topic":"Compressed Air System","kind":"fact","front":"What are the functions of an air receiver?","back":"It dampens pulsation from the compressor, acts as a reservoir for sudden demand above compressor capacity, prevents short cycling, and lets moisture carried over from the after-coolers settle out.","explain":"Place a receiver near a load with sudden, short-lived high demand to avoid adding compressor capacity. The book wants receivers generously sized for a large cooling surface.","flash":false,"source":"BEE Book 3 Ch 03 p121","order":3211},
{"id":"p3-b03-031","paper":3,"topic":"Compressed Air System","kind":"problem","front":"Using the IS 7938 rule of thumb quoted in the book, what receiver volume suits a compressor delivering 12 m³/min?","back":"Between 1.2 m³ and 2.0 m³, that is one-tenth to one-sixth of the output per minute.","explain":"The book wants the receiver generously sized to give a large cooling surface and to even out pulsation from a reciprocating compressor.","flash":false,"steps":[{"prompt":"Find the lower limit.","answer":"12 / 10 = 1.2 m³.","explain":"One-tenth of the output in m³/min."},{"prompt":"Find the upper limit.","answer":"12 / 6 = 2.0 m³.","explain":"One-sixth of the output in m³/min."},{"prompt":"Pick a size within the range.","answer":"Any volume from 1.2 to 2.0 m³; the larger end gives more cooling surface and smoother pressure.","explain":"The rule is a range, not a single answer, so the choice depends on the load pattern."}],"source":"BEE Book 3 Ch 03 p121","order":3212},
{"id":"p3-b03-032","paper":3,"topic":"Compressed Air System","kind":"fact","front":"What air velocity range is usual in compressed air mains, and why?","back":"6 to 10 m/s. This keeps pressure drop low on most systems and lets moisture precipitate.","explain":"Pipe size is chosen from the allowable velocity and then checked against pressure drop. Mains should slope down toward a dead end, with traps at all low points.","flash":false,"source":"BEE Book 3 Ch 03 p121","order":3213},
{"id":"p3-b03-033","paper":3,"topic":"Compressed Air System","kind":"problem","front":"Size a compressed air main for 200 cfm (5.66 m³/min free air) delivered at 7.0 kg/cm² gauge, with a velocity limit of 6 m/s. What is the pipe bore?","back":"About 0.0538 m (53.8 mm), so a 2 inch nominal bore pipe is chosen.","explain":"The book uses 7.0 directly in the gas-law step. The method is area equals flow divided by velocity, then diameter from the circle area.","flash":false,"steps":[{"prompt":"Convert to inlet-equivalent flow.","answer":"Q = 5.66 × 1.013 / 7.0 = 0.819 m³/min.","explain":"Constant-temperature gas law, P₁V₁ = P₂V₂, as the book applies it."},{"prompt":"Convert to m³/s.","answer":"0.819 / 60 = 0.01365 m³/s.","explain":"Velocity is in m/s, so flow must be in m³/s."},{"prompt":"Find the required pipe area.","answer":"A = Q / v = 0.01365 / 6 = 2.275 × 10⁻³ m².","explain":"Area equals flow divided by allowable velocity."},{"prompt":"Find the diameter.","answer":"D = √(4A / π) = 0.0538 m, about 2.11 inch. Choose 2 inch nominal bore.","explain":"Round up to the next standard nominal bore."}],"source":"BEE Book 3 Ch 03 p122","order":3214},
{"id":"p3-b03-034","paper":3,"topic":"Compressed Air System","kind":"fact","front":"What share of capacity or efficiency can a worn compressor valve cost?","back":"A worn valve can cut capacity by as much as 20% (Section 3.6). The checklist warns that worn valves can reduce efficiency by as much as 50%, so inspect valves about every six months.","explain":"The two figures come from different parts of the chapter, so answer with the one the question asks for and note the difference. A periodic FAD test reveals the loss, and deviations above 10% need corrective action.","flash":false,"source":"BEE Book 3 Ch 03 p123","order":3215},
{"id":"p3-b03-035","paper":3,"topic":"Compressed Air System","kind":"problem","front":"A pump-up test uses a total storage volume of 8.287 m³ (receiver 7.79 m³ plus 0.4974 m³ hold-up). Pressure rises from 0.5 to 7.03 kg/cm² in 4.021 min, atmospheric is 1.026 kg/cm² abs, and rated capacity is 14.75 m³/min. Find the output and the shortfall.","back":"Output about 13.12 m³/min. Shortfall 1.63 m³/min, or 11.05%, so the compressor needs investigation.","explain":"The formula assumes the discharge air is at ambient temperature (perfect isothermal compression). If discharge air is hotter, multiply by (273 + ambient) / (273 + discharge) as the book describes.","flash":false,"steps":[{"prompt":"Find the total storage volume.","answer":"7.79 + 0.4974 = 8.287 m³.","explain":"Receiver plus additional hold-up volume in the pipe and cooler."},{"prompt":"Find the output.","answer":"(7.03 − 0.5) × 8.287 / (1.026 × 4.021) = 54.11 / 4.126 = 13.12 m³/min.","explain":"Pressure rise times volume, divided by atmospheric pressure times pump-up time."},{"prompt":"Find the shortfall against the rating.","answer":"14.75 − 13.12 = 1.63 m³/min.","explain":"The rated capacity is 14.75 m³/min at 7 kg/cm²."},{"prompt":"Find the percentage shortfall.","answer":"1.63 / 14.75 × 100 = 11.05%.","explain":"A deviation above 10% calls for corrective measures."}],"source":"BEE Book 3 Ch 03 p124","order":3216},
{"id":"p3-b03-036","paper":3,"topic":"Compressed Air System","kind":"fact","front":"Why are ball, plug or gate valves preferred over globe valves in compressed air lines?","back":"Globe valves cause a high pressure drop, so ball, plug or gate valves are preferred.","explain":"Fittings also create pressure loss, quantified as equivalent lengths in Table 3.12. Welded joints in place of screwed or flexible joints reduce both leakage and pressure drop.","flash":false,"source":"BEE Book 3 Ch 03 p126","order":3217},
{"id":"p3-b03-037","paper":3,"topic":"Compressed Air System","kind":"fact","front":"How much more energy do pneumatic transport and pneumatic tools use compared with mechanical or electric alternatives?","back":"Pneumatic transport uses about 8 times more energy than mechanical systems. Pneumatic drills and grinders use about 20 times more than motor-driven tools.","explain":"Table 3.15 shows a pneumatic jet grinder at 3.59 kW against 0.18 kW for an electric straight grinder, about 20 times. Safety overrides energy saving, so electric tools are not allowed where flammable vapours are present.","flash":true,"source":"BEE Book 3 Ch 03 p126","order":3218},
{"id":"p3-b03-038","paper":3,"topic":"Compressed Air System","kind":"fact","front":"How much of a plant's compressed air can leakage account for, and what is the first step?","back":"Leakage of 40–50% is not uncommon. The first step is periodic leak tests to estimate the quantity lost.","explain":"Leaks mostly occur at receivers, relief valves, pipe and hose joints, shut-off valves, quick-release couplings and tools, usually from poor maintenance or poor installation.","flash":true,"source":"BEE Book 3 Ch 03 p126","order":3219},
{"id":"p3-b03-039","paper":3,"topic":"Compressed Air System","kind":"problem","front":"In an automobile plant, a pump-up test uses a 4100 L receiver and piping volume. Pressure rises from 1 to 8.5 kg/cm² gauge in 65 s. Atmospheric is 1.026 kg/cm² abs, ambient 32°C and final air temperature 52°C. Find the FAD in m³/min and in cfm.","back":"About 25.96 m³/min, or about 916 cfm.","explain":"Hot discharge air is corrected back to ambient conditions with the temperature ratio, which lowers the raw output of 27.66 m³/min by about 6%.","flash":false,"steps":[{"prompt":"Convert units.","answer":"4100 L = 4.1 m³; 65 s = 1.0833 min.","explain":"The formula works in m³ and minutes."},{"prompt":"Find the pressure term.","answer":"(8.5 − 1) / 1.026 = 7.31.","explain":"Gauge pressure rise divided by atmospheric pressure."},{"prompt":"Find the uncorrected output.","answer":"7.31 × 4.1 / 1.0833 = 27.66 m³/min.","explain":"Pressure term times volume, divided by pump-up time."},{"prompt":"Apply the temperature correction.","answer":"27.66 × (273 + 32) / (273 + 52) = 27.66 × 305/325 = 25.96 m³/min.","explain":"Converts the hot discharge air back to ambient inlet conditions."},{"prompt":"Convert to cfm.","answer":"25.96 × 3.28³ ≈ 916 cfm.","explain":"One cubic metre per minute is about 35.3 cfm."}],"source":"BEE Book 3 Ch 03 p127","order":3220},
{"id":"p3-b03-040","paper":3,"topic":"Compressed Air System","kind":"problem","front":"On the same system and compressor (FAD 916 cfm), a leakage test with no pneumatic equipment running shows 3 min on load and 13 min unloaded, with 145 kW drawn on load. Find the leakage percentage, the leakage in cfm, the specific power and the power lost to leakage.","back":"18.75%; 171.75 cfm; 0.1583 kW/cfm; about 27.19 kW lost.","explain":"The leak fraction is load time over the total cycle. The leak flow then carries the compressor's specific power with it, which gives the power wasted.","flash":false,"steps":[{"prompt":"Find the leakage percentage.","answer":"T / (T + t) × 100 = 3 / 16 × 100 = 18.75%.","explain":"Load time as a fraction of the total cycle."},{"prompt":"Find the leakage quantity.","answer":"0.1875 × 916 = 171.75 cfm.","explain":"Applies the leak fraction to the FAD."},{"prompt":"Find the specific power.","answer":"145 / 916 = 0.1583 kW/cfm.","explain":"Full-load power per cfm of delivered air."},{"prompt":"Find the power lost to leakage.","answer":"171.75 × 0.1583 = 27.19 kW.","explain":"Leak flow times specific power."}],"source":"BEE Book 3 Ch 03 p128","order":3221},
{"id":"p3-b03-041","paper":3,"topic":"Compressed Air System","kind":"problem","front":"A receiver of 0.3 m³, plus 0.05 m³ of hold-up pipe and cooler, is pumped from 0 to 7 kg/cm² gauge in 4.1 min. Air temperature rises from 35°C to 50°C. Atmospheric is 1.026 kg/cm² abs. Find the FAD in m³/h.","back":"About 33 m³/h (0.555 m³/min).","explain":"This is the same pump-up method as the worked examples. The temperature ratio corrects the hotter discharge air back to inlet conditions.","flash":false,"steps":[{"prompt":"Find the total volume.","answer":"0.3 + 0.05 = 0.35 m³.","explain":"Receiver plus hold-up volume."},{"prompt":"Find the pressure term.","answer":"7 / 1.026 = 6.823.","explain":"Gauge pressure rise divided by atmospheric pressure."},{"prompt":"Find the uncorrected output.","answer":"6.823 × 0.35 / 4.1 = 0.5824 m³/min.","explain":"Pressure term times volume, divided by pump-up time."},{"prompt":"Apply the temperature correction.","answer":"0.5824 × (273 + 35) / (273 + 50) = 0.5824 × 308/323 = 0.5554 m³/min.","explain":"Converts discharge air at 50°C back to the 35°C inlet reference."},{"prompt":"Convert to m³/h.","answer":"0.5554 × 60 = 33.3 m³/h.","explain":"Multiply m³/min by 60 for the hourly FAD."}],"source":"BEE Book 3 Ch 03 p130","order":3222},
{"id":"p3-b04-001","paper":3,"topic":"Refrigeration basics","kind":"fact","front":"What is refrigeration, in terms of heat transfer?","back":"The removal and relocation of heat: it moves heat from a low-temperature source to a high-temperature sink, using a low-boiling refrigerant.","explain":"Heat does not flow from cold to hot naturally, so external energy (electricity or heat) must drive mechanical equipment to do it. The refrigerant is chosen because it boils at a low temperature, absorbing heat from the cold side.","flash":true,"source":"BEE Book 3 Ch 04 p135","order":3223},
{"id":"p3-b04-002","paper":3,"topic":"Refrigeration basics","kind":"fact","front":"Name the five heat transfer loops in an HVAC and refrigeration system, from the indoor space to the outdoors.","back":"1) Indoor air loop (supply air fan through the cooling coil); 2) chilled water loop (pump returns water from the coil to the chiller evaporator); 3) refrigerant loop (compressor pumps heat to the condenser water); 4) condenser water loop (pump sends heat to the cooling tower); 5) cooling tower loop (fan drives air across the hot water to the outdoors).","explain":"Thermal energy moves through these five loops in sequence, each passing the heat to the next. Tracing the loop order helps locate where a fault or inefficiency sits in the system.","flash":false,"source":"BEE Book 3 Ch 04 p135","order":3224},
{"id":"p3-b04-003","paper":3,"topic":"Psychrometrics","kind":"fact","front":"Name five properties of air that a psychrometric chart shows.","back":"Any five of: dry-bulb temperature, wet-bulb temperature, dew point, specific humidity, relative humidity, enthalpy (kJ/kg dry air), specific volume (m³/kg).","explain":"The chart shows these properties on one diagram. It lets an engineer turn a heating or cooling load in kW or TR into an air volume flow in m³/s or cfm for the duct system.","flash":false,"source":"BEE Book 3 Ch 04 p136","order":3225},
{"id":"p3-b04-004","paper":3,"topic":"Psychrometrics","kind":"problem","front":"What are the specific humidity, enthalpy, wet-bulb temperature, dew point and specific volume of air at 32°C dry-bulb and 60% RH?","back":"About 18 g moisture/kg dry air; 78 kJ/kg dry air; wet-bulb 25.5°C; dew point 23°C; specific volume 0.89 m³/kg.","explain":"This is the book's chart-reading example (Figure 4.2). Reading the chart correctly needs the dry-bulb line and the 60% RH curve to cross exactly. Practise reading all five values from one point.","flash":false,"source":"BEE Book 3 Ch 04 p136","steps":[{"prompt":"Locate 32°C on the dry-bulb axis and move up to the 60% RH curve.","answer":"That intersection is the air state point.","explain":"Every property is read from this single point."},{"prompt":"Read the specific humidity at that point.","answer":"About 18 g moisture per kg of dry air (0.018 kg/kg).","explain":"Specific humidity is the mass of water vapour per mass of dry air."},{"prompt":"Read the enthalpy at that point.","answer":"About 78 kJ/kg of dry air.","explain":"Enthalpy is the total heat content, used for cooling and heating loads."},{"prompt":"Read the wet-bulb temperature, dew point and specific volume.","answer":"Wet-bulb about 25.5°C; dew point about 23°C; specific volume about 0.89 m³/kg.","explain":"Specific volume converts a mass flow into a volume flow for the ducts."}],"order":3226},
{"id":"p3-b04-005","paper":3,"topic":"Psychrometrics","kind":"fact","front":"What is the human comfort zone on a psychrometric chart?","back":"Dry-bulb temperature 22–27°C with relative humidity 40–60%.","explain":"Most people feel comfortable inside this zone. Air conditioning uses the chart to decide whether air must be heated or cooled, humidified or dehumidified to bring it into the zone.","flash":false,"source":"BEE Book 3 Ch 04 p137","order":3227},
{"id":"p3-b04-006","paper":3,"topic":"Psychrometrics","kind":"problem","front":"Outdoor air at 35°C and 60% RH is cooled and reheated to 24°C and 53% RH. How much moisture is removed, how much heat is removed, and how much heat is added?","back":"Moisture removed about 11.5 g/kg dry air; heat removed about 48 kJ/kg dry air (cooling); heat added about 10 kJ/kg dry air (reheating).","explain":"Cooling below the dew point condenses moisture, and reheating raises the temperature without changing moisture. The book labels the states 1 (outdoor air), 2 (saturated, 100% RH) and 3 (comfort zone).","flash":false,"source":"BEE Book 3 Ch 04 p137","steps":[{"prompt":"Plot state 1: 35°C dry bulb at 60% RH.","answer":"This is the outdoor air state.","explain":"The process starts from the outdoor condition."},{"prompt":"Find the moisture removed between state 1 and the saturated state 2.","answer":"About 11.5 g moisture removed per kg of dry air.","explain":"The moisture falls out as liquid when the air is cooled to saturation."},{"prompt":"Find the heat removed in the cooling step (1 to 2).","answer":"About 48 kJ/kg dry air (qcool).","explain":"This is the enthalpy difference across the cooling coil."},{"prompt":"Plot state 3 at 24°C and 53% RH, then find the heat added in reheating (2 to 3).","answer":"About 10 kJ/kg dry air (qheat).","explain":"Reheating raises the temperature at constant moisture content."}],"order":3228},
{"id":"p3-b04-007","paper":3,"topic":"Refrigeration cycles","kind":"fact","front":"What drives vapour compression refrigeration (VCR) and what drives vapour absorption refrigeration (VAR)?","back":"VCR is driven by mechanical energy (a compressor); VAR is driven by thermal energy (steam, hot water, gas, oil or waste heat).","explain":"Both move heat from low to high temperature. VAR still needs some electricity for its pumps, which is why it suits sites with waste heat.","flash":false,"source":"BEE Book 3 Ch 04 p138","order":3229},
{"id":"p3-b04-008","paper":3,"topic":"Refrigeration basics","kind":"fact","front":"What are small, medium and large refrigeration plant capacities in TR?","back":"Small: up to 50 TR; medium: 50–250 TR; large: over 250 TR.","explain":"The book uses these bands when comparing plant options. A large industry may run a bank of such units, sharing chilled water pumps, condenser pumps and cooling towers as an off-site utility.","flash":true,"source":"BEE Book 3 Ch 04 p138","order":3230},
{"id":"p3-b04-009","paper":3,"topic":"Refrigerants","kind":"fact","front":"Is the absorber a component of a vapour compression refrigeration cycle?","back":"No. A VCR cycle uses a compressor, condenser, expansion device and evaporator. The absorber belongs to absorption (VAR) systems.","explain":"In VAR, refrigerant vapour is absorbed into a lithium bromide solution in the absorber. Exam questions often use the absorber as a trap option in VCR lists.","flash":true,"source":"BEE Book 3 Ch 04 p139","order":3231},
{"id":"p3-b04-010","paper":3,"topic":"Refrigerants","kind":"fact","front":"What did the Montreal Protocol (1987) require for CFC refrigerants, and when did India complete its CFC phase-out?","back":"A phased reduction in ozone-depleting CFC production, with an eventual stop by 1996. India completed the CFC phase-out on 1 August 2008.","explain":"The Copenhagen agreement (1992) followed. CFCs damage the ozone layer, so the industry moved to HCFCs and then HFCs. Keep the years 1987, 1996 and 2008 in mind for exam questions.","flash":true,"source":"BEE Book 3 Ch 04 p140","order":3232},
{"id":"p3-b04-011","paper":3,"topic":"Refrigerants","kind":"fact","front":"What is the HCFC phase-out schedule for Article 5 parties under the 19th Meeting of Parties (MOP)?","back":"Base level is the average of 2009 and 2010. Freeze at base level in 2013; 10% reduction in 2015; 35% in 2020; 67.5% in 2025; 100% in 2030, followed by a 2.5% average annual service tail in 2030–2040.","explain":"The 19th MOP accelerated the phase-out of HCFC production and consumption. The schedule is dated, so confirm current figures with the Ministry of Environment and Forests (Ozone Cell) before relying on it.","flash":false,"source":"BEE Book 3 Ch 04 p140","order":3233},
{"id":"p3-b04-012","paper":3,"topic":"Absorption refrigeration","kind":"fact","front":"What is the typical COP of a Li-Br–water absorption chiller, and what chilled water temperature can it give with 30°C cooling water?","back":"COP 0.65–0.70; it gives chilled water at 6.7°C. Systems giving chilled water at 3°C are also available.","explain":"This COP is thermal: cooling output per unit of heat input. It should not be compared directly with the electric COP of a compression chiller.","flash":true,"source":"BEE Book 3 Ch 04 p142","order":3234},
{"id":"p3-b04-013","paper":3,"topic":"Compressors","kind":"fact","front":"Why can older centrifugal compressors not reduce load much below about 50%?","back":"Surge: as flow is choked off, the gas does not gain enough energy to overcome discharge pressure. Flow drops abruptly, the gas oscillates back and forth in the impeller, efficiency falls and vibration can damage the machine.","explain":"Many older machines handle low loads with hot gas bypass, which wastes the unneeded cooling output. Newer machines combine variable-speed drives with inlet guide vanes to reach about 20% load.","flash":false,"source":"BEE Book 3 Ch 04 p144","order":3235},
{"id":"p3-b04-014","paper":3,"topic":"Compressors","kind":"fact","front":"How do screw compressors usually control capacity, and when can a variable-speed drive be used on them?","back":"Usually with a slide valve forming part of the housing around the screws. A variable-speed drive is limited to oil-injected compressors, because slowing a dry compressor allows excessive internal leakage.","explain":"Screw compressors suit higher condensing pressures, such as with HCFC-22 and ammonia, and are compact. Part-load efficiency depends strongly on the capacity control method used.","flash":false,"source":"BEE Book 3 Ch 04 p145","order":3236},
{"id":"p3-b04-015","paper":3,"topic":"Chiller energy","kind":"fact","front":"What four power inputs make up the overall kW/TR of a centralised chilled water plant?","back":"Compressor, chilled water pump, condenser water pump and cooling tower fan. The overall kW/TR is the sum of the kW/TR of each.","explain":"Compressor power alone understates the true plant energy use. Pump and fan power must be added to get the total specific power consumption.","flash":false,"source":"BEE Book 3 Ch 04 p150","order":3237},
{"id":"p3-b04-016","paper":3,"topic":"Refrigeration performance","kind":"problem","front":"What is the ideal (Carnot) COP for an evaporator at -15°C and a condenser at 30°C?","back":"About 5.7 (5.74), using absolute temperatures: 258.15 / (303.15 − 258.15).","explain":"The Carnot COP is an upper limit set only by the two temperatures. Real compressors have lower COP because of losses, so the book uses the actual cooling effect divided by compressor input for industry COP.","flash":false,"source":"BEE Book 3 Ch 04 p150","steps":[{"prompt":"Convert the evaporator (-15°C) and condenser (30°C) temperatures to kelvin.","answer":"Evaporator 258.15 K; condenser 303.15 K.","explain":"Carnot formulas need absolute temperatures."},{"prompt":"Find the temperature lift.","answer":"303.15 − 258.15 = 45 K.","explain":"The lift is the condenser temperature minus the evaporator temperature."},{"prompt":"Apply COP(Carnot) = T_evap / (T_cond − T_evap).","answer":"258.15 / 45 = 5.74.","explain":"Higher evaporator temperature or lower condenser temperature raises this value."},{"prompt":"Interpret the result.","answer":"Ideal COP of about 5.7; a real compressor will achieve less.","explain":"The Carnot figure ignores compressor type, so it is a benchmark, not a prediction."}],"order":3238},
{"id":"p3-b04-017","paper":3,"topic":"Chiller energy","kind":"fact","front":"What parameters must be measured to estimate chiller performance in kW/TR?","back":"Chilled water inlet and outlet temperatures (instrument least count about 0.1°C) and chilled water flow; condenser water inlet and outlet temperatures and flow; and power input to the compressor, chilled water pump, condenser water pump and cooling tower fan.","explain":"Flow can be read from an ultrasonic meter or inferred from pump duty. Design flows are about 0.68 m³/h per TR for chilled water and 0.91 m³/h per TR for condenser water.","flash":false,"source":"BEE Book 3 Ch 04 p151","order":3239},
{"id":"p3-b04-018","paper":3,"topic":"Refrigeration performance","kind":"fact","front":"What is the Integrated Part Load Value (IPLV), and which four load points does it use?","back":"IPLV is a part-load efficiency reference using 100%, 75%, 50% and 25% of capacity, each given equal weight.","explain":"The book calls IPLV the most appropriate reference, though not the best, because equal weighting ignores that equipment usually runs at 50–75% of capacity. Full-load kW/TR reflects design conditions that may occur only about 1% of the time.","flash":false,"source":"BEE Book 3 Ch 04 p152","order":3240},
{"id":"p3-b04-019","paper":3,"topic":"Refrigeration performance","kind":"problem","front":"What is the cooling load in TR for a medium-size office of 1000 m² with central air conditioning?","back":"About 60 TR, using the indicative load of 0.06 TR/m².","explain":"The book's profile is indicative only. A real design needs a detailed heat load calculation that includes people, lighting, envelope and air ingress.","flash":false,"source":"BEE Book 3 Ch 04 p152","steps":[{"prompt":"Pick the matching profile.","answer":"Medium-size office, 10–30 people, central A/C: 0.06 TR/m².","explain":"The book gives three indicative profiles by building type."},{"prompt":"Calculate the load.","answer":"1000 m² × 0.06 TR/m² = 60 TR.","explain":"TR load equals floor area times the profile value."},{"prompt":"Check against the other profiles.","answer":"Small cabins at 0.1 TR/m² would give 100 TR; large multi-storey complexes at 0.04 TR/m² would give 40 TR.","explain":"The spread shows why building type matters when sizing plant."}],"order":3241}
]$cards$::jsonb);
